await (async page => {
 const capture=()=> [...document.querySelectorAll('body *')].filter(e=>e.getBoundingClientRect().width && e.getBoundingClientRect().height && !['SCRIPT','OPTION'].includes(e.tagName)).map(e=>{
   const s=getComputedStyle(e),r=e.getBoundingClientRect();
   const props=['display','position','color','backgroundColor','backgroundImage','fontFamily','fontSize','fontWeight','lineHeight','paddingTop','paddingRight','paddingBottom','paddingLeft','marginTop','marginBottom','gap','borderTopWidth','borderLeftWidth','borderTopStyle','borderColor','borderRadius','gridTemplateColumns','outlineStyle'];
   return {tag:e.tagName,id:e.id,text:e.children.length?'':e.textContent?.slice(0,35),rect:[r.x,r.y,r.width,r.height].map(n=>Math.round(n*100)/100),style:Object.fromEntries(props.map(p=>[p,s[p]]))};
 });
 const results=[];
 for(const width of [1440]) for(const theme of ["light"]) for(const tab of ["Modal"]) {
   const snapshots=[];
   for(const port of [5180,5181]) {
     await page.setViewportSize({width,height:900});
     await page.goto('http://127.0.0.1:'+port);
     await page.evaluate(theme=>{localStorage.setItem('hairday-lang','pt');localStorage.setItem('hairday-theme',theme)},theme);
     await page.reload(); await page.getByRole('navigation',{name:'Seções'}).getByRole('button',{name:['Grade','Modal'].includes(tab)?'Agenda':tab,exact:true}).click();
     await page.evaluate(()=>document.fonts.ready);
     if(tab==='Agenda') {await page.locator('#schedule-date').fill('2026-11-18'); await page.locator('#agenda-date').fill('2026-11-18');}
     if(tab==='Grade') {await page.getByText('Opções da agenda',{exact:true}).click(); await page.getByRole('button',{name:'Ver grade por profissional',exact:true}).click();}
     if(tab==='Modal') {await page.getByText('Mais opções de agendamento',{exact:true}).click(); await page.getByRole('button',{name:'Cadastro completo',exact:true}).click();}
     snapshots.push(await page.evaluate(capture));
     if(tab==='Agenda') await page.screenshot({path:"C:/Users/User/OneDrive/Documentos/ChatGPT/currency exchange app/hairday-tailwind/docs/tailwind"+'/'+port+'-'+width+'-'+theme+'.png',fullPage:true});
   }
   const differences=[];
   const [a,b]=snapshots;
   if(a.length!==b.length) differences.push({count:[a.length,b.length]});
   for(let i=0;i<Math.min(a.length,b.length);i++) {
     const delta={};
     if(JSON.stringify(a[i].rect)!==JSON.stringify(b[i].rect))delta.rect=[a[i].rect,b[i].rect];
     for(const p of Object.keys(a[i].style)) if(a[i].style[p]!==b[i].style[p])delta[p]=[a[i].style[p],b[i].style[p]];
     if(Object.keys(delta).length)differences.push({i,tag:a[i].tag,id:a[i].id,text:a[i].text,delta});
   }
   results.push({width,theme,tab,differences});
 }
 return results;
 })(page);
